import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.Arrays;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());int[] boys = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {boys[i] = Integer.parseInt(st.nextToken());}int m = Integer.parseInt(br.readLine());int[] girls = new int[m];st = new StringTokenizer(br.readLine());for (int i = 0; i < m; i++) {girls[i] = Integer.parseInt(st.nextToken());}Arrays.sort(boys);Arrays.sort(girls);int pairs = 0;int i = 0, j = 0;while (i < n && j < m) {if (Math.abs(boys[i] - girls[j]) <= 1) {pairs++;i++;j++;} else if (boys[i] < girls[j]) {i++;} else {j++;}}System.out.println(pairs);}}